def _parse(v):
    v = v.split('+', 1)[0]
    if '-' in v:
        core, pre = v.split('-', 1)
    else:
        core, pre = v, None
    major, minor, patch = core.split('.')
    major, minor, patch = int(major), int(minor), int(patch)
    if pre is None:
        pre_ids = None
    else:
        pre_ids = pre.split('.')
    return major, minor, patch, pre_ids

def _is_num(s):
    return s.isdigit()

def _cmp_pre(a_ids, b_ids):
    for a, b in zip(a_ids, b_ids):
        a_num = _is_num(a)
        b_num = _is_num(b)
        if a_num and b_num:
            ai, bi = int(a), int(b)
            if ai != bi:
                return -1 if ai < bi else 1
        elif a_num != b_num:
            return -1 if a_num else 1
        else:
            if a != b:
                return -1 if a < b else 1
    if len(a_ids) == len(b_ids):
        return 0
    return -1 if len(a_ids) < len(b_ids) else 1

def cmp_semver(a, b):
    ma, mi, pa, prea = _parse(a)
    mb, mj, pb, preb = _parse(b)
    if ma != mb:
        return -1 if ma < mb else 1
    if mi != mj:
        return -1 if mi < mj else 1
    if pa != pb:
        return -1 if pa < pb else 1
    if prea is None and preb is None:
        return 0
    if prea is None:
        return 1
    if preb is None:
        return -1
    return _cmp_pre(prea, preb)
```

