import re

def parse_range(header, size):
    if not isinstance(header, str):
        return None
    try:
        unit, ranges = header.split('=', 1)
    except ValueError:
        return None
    if unit.strip().lower() != 'bytes':
        return None

    result = []
    for part in ranges.split(','):
        part = part.replace(' ', '')
        if not part:
            return None
        m = re.fullmatch(r'(\d*)-(\d*)', part)
        if not m:
            return None
        start_s, end_s = m.groups()
        if start_s == '' and end_s == '':
            return None
        try:
            if start_s == '':
                suffix = int(end_s)
                if suffix <= 0:
                    continue
                start = size - suffix
                if start < 0:
                    start = 0
                end = size - 1
            elif end_s == '':
                start = int(start_s)
                if start >= size:
                    continue
                end = size - 1
            else:
                start = int(start_s)
                end = int(end_s)
                if start >= size:
                    continue
                if end >= size:
                    end = size - 1
                if start > end:
                    continue
        except ValueError:
            return None
        if start > end:
            continue
        result.append((start, end))

    return result if result else None
```

