def unified_diff(a, b, context=3):
    if a == b:
        return []
    from difflib import SequenceMatcher

    sm = SequenceMatcher(None, a, b)
    opcodes = sm.get_opcodes()

    entries = []
    a_pos = 0
    b_pos = 0
    for tag, i1, i2, j1, j2 in opcodes:
        if tag == 'equal':
            for _ in range(i1, i2):
                entries.append((' ', a_pos, b_pos))
                a_pos += 1
                b_pos += 1
        elif tag == 'delete':
            for _ in range(i1, i2):
                entries.append(('-', a_pos, b_pos))
                a_pos += 1
        elif tag == 'insert':
            for _ in range(j1, j2):
                entries.append(('+', a_pos, b_pos))
                b_pos += 1
        elif tag == 'replace':
            for _ in range(i1, i2):
                entries.append(('-', a_pos, b_pos))
                a_pos += 1
            for _ in range(j1, j2):
                entries.append(('+', a_pos, b_pos))
                b_pos += 1

    n = len(entries)
    if n == 0:
        return []

    change_blocks = []
    i = 0
    while i < n:
        if entries[i][0] != ' ':
            start = i
            while i < n and entries[i][0] != ' ':
                i += 1
            end = i - 1
            change_blocks.append((start, end))
        else:
            i += 1

    windows = []
    for start_block, end_block in change_blocks:
        w_start = max(0, start_block - context)
        w_end = min(n - 1, end_block + context)
        if windows and w_start <= windows[-1][1]:
            prev_start, prev_end = windows[-1]
            windows[-1] = (prev_start, max(prev_end, w_end))
        else:
            windows.append((w_start, w_end))

    out = []
    for w_start, w_end in windows:
        first_tag, first_a, first_b = entries[w_start]
        a_start = first_a + 1
        b_start = first_b + 1
        alen = 0
        blen = 0
        for tag, ai, bi in entries[w_start:w_end + 1]:
            if tag in (' ', '-'):
                alen += 1
            if tag in (' ', '+'):
                blen += 1
        out.append(f"@@ -{a_start},{alen} +{b_start},{blen} @@")
        for tag, ai, bi in entries[w_start:w_end + 1]:
            if tag == ' ':
                line = a[ai]
            elif tag == '-':
                line = a[ai]
            else:
                line = b[bi]
            out.append(f"{tag}{line}")
    return out
