class _Node:
    __slots__ = ('key', 'val', 'freq')
    def __init__(self, key, val, freq=1):
        self.key = key
        self.val = val
        self.freq = freq

class LFUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.minfreq = 0
        self.key_to_node = {}
        self.freq_to_keys = {}  # freq -> {key: node} ordered by recency

    def _increase(self, node):
        f = node.freq
        d = self.freq_to_keys.get(f)
        if d:
            del d[node.key]
            if not d:
                del self.freq_to_keys[f]
                if f == self.minfreq:
                    self.minfreq += 1
        node.freq += 1
        nf = node.freq
        if nf not in self.freq_to_keys:
            self.freq_to_keys[nf] = {}
        self.freq_to_keys[nf][node.key] = node

    def get(self, key):
        node = self.key_to_node.get(key)
        if not node:
            return -1
        self._increase(node)
        return node.val

    def put(self, key, value):
        if self.cap == 0:
            return
        if key in self.key_to_node:
            node = self.key_to_node[key]
            node.val = value
            self._increase(node)
            return
        if len(self.key_to_node) >= self.cap:
            d = self.freq_to_keys[self.minfreq]
            evict_key = next(iter(d))
            del d[evict_key]
            if not d:
                del self.freq_to_keys[self.minfreq]
            del self.key_to_node[evict_key]
        node = _Node(key, value, 1)
        self.key_to_node[key] = node
        if 1 not in self.freq_to_keys:
            self.freq_to_keys[1] = {}
        self.freq_to_keys[1][key] = node
        self.minfreq = 1
