import heapq

def topk(stream, k):
    if k <= 0:
        return []
    heap = []
    for idx, pair in enumerate(stream):
        value, label = pair
        item = (value, idx, label)
        if len(heap) < k:
            heapq.heappush(heap, item)
        else:
            worst_val, worst_idx, _ = heap[0]
            if value > worst_val or (value == worst_val and idx < worst_idx):
                heapq.heapreplace(heap, item)
    heap.sort(key=lambda x: (-x[0], x[1]))
    return [(v, lab) for v, _, lab in heap]
```

