from datetime import datetime, timedelta

def _parse_field(s, min_v, max_v):
    if not s:
        raise ValueError("empty field")
    res = set()
    for part in s.split(','):
        if '/' in part:
            base, step_s = part.split('/', 1)
            try:
                step = int(step_s)
            except ValueError:
                raise ValueError(f"bad step {part}")
            if step <= 0:
                raise ValueError(f"step must be >0 {part}")
            if base == '*':
                start, end = min_v, max_v
            elif '-' in base:
                a, b = base.split('-', 1)
                try:
                    start, end = int(a), int(b)
                except ValueError:
                    raise ValueError(f"bad range {part}")
            else:
                try:
                    start = int(base)
                except ValueError:
                    raise ValueError(f"bad base {part}")
                end = max_v
            if not (min_v <= start <= max_v and min_v <= end <= max_v):
                raise ValueError(f"range out of bounds {part}")
            if start > end:
                raise ValueError(f"invalid range {part}")
            for v in range(start, end + 1, step):
                if min_v <= v <= max_v:
                    res.add(v)
        elif '-' in part:
            a, b = part.split('-', 1)
            try:
                start, end = int(a), int(b)
            except ValueError:
                raise ValueError(f"bad range {part}")
            if start > end or not (min_v <= start <= max_v and min_v <= end <= max_v):
                raise ValueError(f"invalid range {part}")
            for v in range(start, end + 1):
                res.add(v)
        elif part == '*':
            for v in range(min_v, max_v + 1):
                res.add(v)
        else:
            try:
                v = int(part)
            except ValueError:
                raise ValueError(f"bad value {part}")
            if not (min_v <= v <= max_v):
                raise ValueError(f"value out of bounds {part}")
            res.add(v)
    return res

def next_fire(expr, after):
    parts = expr.strip().split()
    if len(parts) != 5:
        raise ValueError("cron expression must have 5 fields")
    min_s, hour_s, dom_s, month_s, dow_s = parts

    minute_set = _parse_field(min_s, 0, 59)
    hour_set = _parse_field(hour_s, 0, 23)
    dom_set = _parse_field(dom_s, 1, 31)
    month_set = _parse_field(month_s, 1, 12)
    dow_set = _parse_field(dow_s, 0, 7)
    # normalize 7 -> 0
    dow_norm = set()
    for v in dow_set:
        if v == 7:
            dow_norm.add(0)
        else:
            dow_norm.add(v)
    dow_set = dow_norm

    dom_star = dom_s == '*'
    dow_star = dow_s == '*'

    cand = after.replace(second=0, microsecond=0)
    if cand <= after:
        cand += timedelta(minutes=1)

    # safety limit
    limit = cand + timedelta(days=5 * 366)
    while cand <= limit:
        if cand.month in month_set and cand.hour in hour_set and cand.minute in minute_set:
            cron_dow = (cand.weekday() + 1) % 7
            dom_match = cand.day in dom_set
            dow_match = cron_dow in dow_set
            if dom_star and dow_star:
                day_ok = True
            elif not dom_star and not dow_star:
                day_ok = dom_match or dow_match
            elif not dom_star:
                day_ok = dom_match
            else:
                day_ok = dow_match
            if day_ok:
                return cand
        cand += timedelta(minutes=1)
    raise ValueError("no matching fire time found")
