def window_medians(a, k):
    n = len(a)
    if k <= 0 or k > n:
        return []
    left = []
    right = []
    to_remove = {}
    left_cnt = 0
    right_cnt = 0

    def clean_left():
        while left:
            v = -left[0]
            if to_remove.get(v, 0):
                heapq.heappop(left)
                to_remove[v] -= 1
                if to_remove[v] == 0:
                    del to_remove[v]
            else:
                break

    def clean_right():
        while right:
            v = right[0]
            if to_remove.get(v, 0):
                heapq.heappop(right)
                to_remove[v] -= 1
                if to_remove[v] == 0:
                    del to_remove[v]
            else:
                break

    def rebalance():
        nonlocal left_cnt, right_cnt
        if left_cnt > right_cnt + 1:
            clean_left()
            v = -heapq.heappop(left)
            left_cnt -= 1
            heapq.heappush(right, v)
            right_cnt += 1
        elif left_cnt < right_cnt:
            clean_right()
            v = heapq.heappop(right)
            right_cnt -= 1
            heapq.heappush(left, -v)
            left_cnt += 1
        clean_left()
        clean_right()
