            lv = -heapq.heappop(left); left_cnt -= 1
            rv = heapq.heappop(right); right_cnt -= 1
            heapq.heappush(left, -rv); left_cnt += 1
            heapq.heappush(right, lv); right_cnt += 1

    def add(val):
