        if not left or val <= -left[0]:
            heapq.heappush(left, -val)
            left_cnt += 1
        else:
            heapq.heappush(right, val)
            right_cnt += 1
        rebalance()

    def remove(val):
        nonlocal left_cnt, right_cnt
        clean_left()
        clean_right()
        if left and val <= -left[0]:
            left_cnt -= 1
        else:
            right_cnt -= 1
        to_remove[val] = to_remove.get(val, 0) + 1
        rebalance()

