class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.components = n
        self.history = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.history.append((rb, ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.components -= 1
        return True

    def snapshot(self):
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            rb, ra, size_ra_before = self.history.pop()
            self.parent[rb] = rb
            self.size[ra] = size_ra_before
            self.components += 1

    def components_count(self):
        return self.components

    # alias to match spec name
    def components(self):
        return self.components
