class WildcardTrie:
    def __init__(self):
        self.word_counts = {}
        self.by_len = defaultdict(set)
        self.index = {}

    def add(self, word):
        c = self.word_counts.get(word, 0) + 1
        self.word_counts[word] = c
        if c == 1:
            L = len(word)
            self.by_len[L].add(word)
            for i, ch in enumerate(word):
                key = (L, i, ch)
                s = self.index.get(key)
                if s is None:
                    s = set()
                    self.index[key] = s
                s.add(word)

    def remove(self, word):
        c = self.word_counts.get(word, 0)
        if c == 0:
            return False
        if c == 1:
            del self.word_counts[word]
            L = len(word)
            s_len = self.by_len[L]
            s_len.discard(word)
            if not s_len:
                del self.by_len[L]
            for i, ch in enumerate(word):
                key = (L, i, ch)
                s = self.index.get(key)
                if s:
                    s.discard(word)
                    if not s:
                        del self.index[key]
        else:
            self.word_counts[word] = c - 1
        return True

    def search(self, pattern):
        L = len(pattern)
        if L not in self.by_len:
            return []
        literals = [(i, ch) for i, ch in enumerate(pattern) if ch != '.']
        if not literals:
            candidates = self.by_len[L]
        else:
            best_set = None
            best_key = None
            best_size = None
            for i, ch in literals:
                key = (L, i, ch)
                s = self.index.get(key)
                if s is None:
                    return []
                if best_size is None or len(s) < best_size:
                    best_size = len(s)
                    best_set = s
                    best_key = key
            candidates = set(best_set)
            for i, ch in literals:
                key = (L, i, ch)
                if key is best_key:
                    continue
                s = self.index.get(key, set())
                candidates.intersection_update(s)
                if not candidates:
                    return []
        return sorted(candidates)
