def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]
    base = len(alphabet)
    neg = n < 0
    n = abs(n)
    digits = []
    while n:
        n, r = divmod(n, base)
        digits.append(alphabet[r])
    res = ''.join(reversed(digits))
    return '-' + res if neg else res


def from_base(s, alphabet):
    if not s:
        raise ValueError('empty string')
    base = len(alphabet)
    mapping = {c: i for i, c in enumerate(alphabet)}
    sign = 1
    if s[0] == '-':
        sign = -1
        s = s[1:]
        if not s:
            raise ValueError('empty digits')
    if not s:
        raise ValueError('empty digits')
    value = 0
    for ch in s:
        if ch not in mapping:
            raise ValueError('character not in alphabet')
        value = value * base + mapping[ch]
    return sign * value
