def parse_csv_stream(chunks):
    def gen():
        for chunk in chunks:
            for ch in chunk:
                yield ch

    it = iter(gen())
    lookahead = None

    def next_char():
        nonlocal lookahead
        if lookahead is not None:
            c = lookahead
            lookahead = None
            return c
        return next(it)

    def peek_char():
        nonlocal lookahead
        if lookahead is None:
            try:
                lookahead = next(it)
            except StopIteration:
                return None
        return lookahead

    in_quote = False
    field = []
    row = []
    any_char = False
    last_newline = False

    def flush_field():
        row.append(''.join(field))
        field.clear()

    try:
        while True:
            c = next_char()
            any_char = True
            if in_quote:
                if c == '"':
                    nxt = peek_char()
                    if nxt == '"':
                        field.append('"')
                        next_char()          # consume second quote
                    else:
                        in_quote = False
                else:
                    field.append(c)
            else:
                if c == '"':
                    in_quote = True
                elif c == ',':
                    flush_field()
                elif c == '\r':
                    if peek_char() == '\n':
                        next_char()
                    flush_field()
                    yield list(row)
                    row = []
                    last_newline = True
                elif c == '\n':
                    flush_field()
                    yield list(row)
                    row = []
                    last_newline = True
                else:
                    field.append(c)
    except StopIteration:
        pass

    if in_quote:
        raise ValueError('unterminated quoted field')
    if not last_newline and any_char:
        row.append(''.join(field))
        if row:
            yield row
