from collections import defaultdict

def shortest_path(graph, src, dst):
    if src == dst:
        return 0, [src]

    INF = 10**30
    dist = {src: 0}
    hops = {src: 0}
    heap = [(0, 0, src)]

    while heap:
        c, h, u = heapq.heappop(heap)
        if dist.get(u) != c or hops.get(u) != h:
            continue
        if u == dst:   # cost/hops are optimal, continue for completeness
            pass
        for v, w in graph.get(u, []):
            nc = c + w
            nh = h + 1
            if v not in dist or nc < dist[v] or (nc == dist[v] and nh < hops.get(v, INF)):
                dist[v] = nc
                hops[v] = nh
                heapq.heappush(heap, (nc, nh, v))

    if dst not in dist:
        return None, []

    # reverse adjacency for tight edges
    rev = defaultdict(list)
    for u, nbrs in graph.items():
        for v, w in nbrs:
            rev[v].append((u, w))

    # nodes that can reach dst using only tight edges
    reachable = set()
    stack = [dst]
    reachable.add(dst)
    while stack:
        node = stack.pop()
        dnode = dist.get(node)
        hnode = hops.get(node)
        if dnode is None:
            continue
        for prev, w in rev.get(node, []):
            if prev in reachable:
                continue
            dprev = dist.get(prev)
            hprev = hops.get(prev)
            if dprev is None or hprev is None:
                continue
            if dprev + w == dnode and hprev + 1 == hnode:
                reachable.add(prev)
                stack.append(prev)

    # reconstruct lexicographically smallest tight path
    path = [src]
    cur = src
    while cur != dst:
        best = None
        dcur = dist.get(cur)
        hcur = hops.get(cur)
        if dcur is None or hcur is None:
            return None, []
        for v, w in graph.get(cur, []):
            if v not in reachable:
                continue
            dv = dist.get(v)
            hv = hops.get(v)
            if dv is None or hv is None:
                continue
            if dcur + w == dv and hcur + 1 == hv:
                if best is None or v < best:
                    best = v
        if best is None:
            return None, []
        path.append(best)
        cur = best

