import heapq

def topo_lex(graph):
    nodes = set(graph.keys())
    indeg = {}
    adj = {}
    for u, succs in graph.items():
        adj[u] = list(succs)
        for v in succs:
            nodes.add(v)
            indeg[v] = indeg.get(v, 0) + 1
    for n in nodes:
        if n not in indeg:
            indeg[n] = 0
        if n not in adj:
            adj[n] = []
    heap = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)
    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj.get(u, []):
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    return result if len(result) == len(nodes) else None
