    entry.alive = true;
    if (!this._events.has(event)) this._events.set(event, []);
    this._events.get(event).push(entry);
  }

  _removeEntry(entry) {
    if (entry.alive !== false) entry.alive = false;
  }

  on(event, fn) {
    const entry = { fn, once: false };
    this._add(event, entry);
    return () => this._removeEntry(entry);
  }

  once(event, fn) {
    const entry = { fn, once: true };
    this._add(event, entry);
    return () => this._removeEntry(entry);
  }

  off(event, fn) {
    const list = this._events.get(event);
    if (!list) return;
    for (const entry of list) {
      if (entry.fn === fn && entry.alive !== false) {
        entry.alive = false;
      }
    }
  }

  emit(event, ...args) {
    const list = this._events.get(event);
    if (!list || list.length === 0) return 0;
    const snapshot = list.slice();
    let invoked = 0;
