function parseQuery(qs) {
  if (typeof qs !== 'string') return {};
  let s = qs;
  if (s.startsWith('?')) s = s.slice(1);
  if (!s) return {};
  const root = {};
  const decode = str => {
    try { return decodeURIComponent(str.replace(/\+/g, ' ')); } catch { return str; }
  };
  const pairs = s.split('&');
  for (const pair of pairs) {
    if (pair === '') continue;
    const eq = pair.indexOf('=');
    let rawKey, rawVal;
    if (eq === -1) { rawKey = pair; rawVal = ''; }
    else { rawKey = pair.slice(0, eq); rawVal = pair.slice(eq + 1); }
    const key = decode(rawKey);
    const val = decode(rawVal);
    const tokens = [];
    const re = /([^\[\]]+)|\[(.*?)\]/g;
    let m;
    while ((m = re.exec(key)) !== null) {
      tokens.push(m[1] !== undefined ? m[1] : m[2]);
    }
    if (tokens.length === 0) continue;
    setValue(root, tokens, val);
  }
  return root;

  function setValue(curRoot, keys, value) {
    let cur = curRoot;
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const isLast = i === keys.length - 1;
      if (isLast) {
        if (k === '') {
          if (!Array.isArray(cur)) cur = [];
          cur.push(value);
        } else if (Array.isArray(cur)) {
          if (/^\d+$/.test(k)) cur[Number(k)] = value;
          else cur[k] = value;
        } else {
          if (Object.prototype.hasOwnProperty.call(cur, k)) {
            const ex = cur[k];
            cur[k] = Array.isArray(ex) ? (ex.push(value), ex) : [ex, value];
          } else {
            cur[k] = value;
          }
        }
      } else {
        if (k === '') {
          if (!Array.isArray(cur)) cur = [];
          const nextKey = keys[i + 1];
          const newContainer = (/^\d+$/.test(nextKey) || nextKey === '') ? [] : {};
          cur.push(newContainer);
          cur = newContainer;
        } else {
          if (!(k in cur) || typeof cur[k] !== 'object' || cur[k] === null) {
            const nextKey = keys[i + 1];
            cur[k] = (/^\d+$/.test(nextKey) || nextKey === '') ? [] : {};
          }
          cur = cur[k];
        }
      }
    }
  }
}

function buildQuery(obj) {
  if (obj == null) return '';
  const pairs = [];
  const enc = s => encodeURIComponent(String(s));
  function partsToKey(parts) {
    let k = enc(parts[0]);
    for (let i = 1; i < parts.length; i++) {
      const p = parts[i];
      k += p === '' ? '[]' : '[' + enc(p) + ']';
    }
    return k;
  }
  function walk(val, parts) {
    if (val === null || val === undefined) {
      pairs.push(partsToKey(parts) + '=');
      return;
    }
    if (Array.isArray(val)) {
      for (let i = 0; i < val.length; i++) walk(val[i], parts.concat(String(i)));
    } else if (typeof val === 'object') {
      const keys = Object.keys(val).sort();
      for (const k of keys) walk(val[k], parts.concat(k));
    } else {
      pairs.push(partsToKey(parts) + '=' + enc(val));
    }
  }
  if (Array.isArray(obj)) {
    obj.forEach((v, i) => walk(v, [String(i)]));
  } else if (typeof obj === 'object') {
    const keys = Object.keys(obj).sort();
    for (const k of keys) walk(obj[k], [k]);
  }
  return pairs.join('&');
