module.exports = function topostortTasks(tasks) {
  for (const name in tasks) {
    const deps = tasks[name].deps || [];
    for (const dep of deps) {
      if (!tasks.hasOwnProperty(dep)) {
        return Promise.reject(new Error(`Unknown dependency ${dep} required by ${name}`));
      }
    }
  }

