  const stack = new Set();
  function dfs(node) {
    if (stack.has(node)) throw new Error('cycle detected');
    if (visited.has(node)) return;
    visited.add(node);
    stack.add(node);
    for (const dep of tasks[node].deps || []) {
      dfs(dep);
    }
    stack.delete(node);
  }
