    for (const name in tasks) dfs(name);
  } catch (e) {
    return Promise.reject(e);
  }

  const memo = {};
  function run(name) {
    if (memo[name]) return memo[name];
    const { deps = [], run: runFn } = tasks[name];
    const depPromises = (deps || []).map(d => run(d));
    const p = Promise.all(depPromises).then(vals => {
      const args = {};
      deps.forEach((d, i) => { args[d] = vals[i]; });
      return runFn(args);
    });
    memo[name] = p;
    return p;
  }

  const names = Object.keys(tasks);
  return Promise.allSettled(names.map(run)).then(results => {
    const out = {};
    let firstErr = null;
    for (let i = 0; i < names.length; i++) {
      const name = names[i];
      const r = results[i];
      if (r.status === 'fulfilled') {
        out[name] = r.value;
      } else {
        if (!firstErr) firstErr = r.reason;
      }
    }
    if (firstErr) return Promise.reject(firstErr);
    return out;
  });
