export function curry<F extends (...args: any[]) => any>(
  f: F
): Curried<Parameters<F>, ReturnType<F>> {
  const run = (...collected: any[]) => {
    return (...next: any[]) => {
      const all = [...collected, ...next];
      if (all.length >= f.length) {
        return f(...(all as Parameters<F>));
      }
      return run(...all);
    };
  };
  return run() as any;
