export function omit<T extends object, K extends readonly (keyof T)[]>(
  obj: T,
  keys: K
): Omit<T, K[number]> {
  const result = {} as any;
  const exclude = new Set(keys as readonly PropertyKey[]);
  for (const key of Object.keys(obj) as Array<keyof T>) {
    if (!exclude.has(key)) {
      result[key] = obj[key];
    }
  }
  return result as Omit<T, K[number]>;
}
