export type DeepPartial<T> =
  T extends Function ? T :
  T extends Array<infer U> ? Array<U> :
  T extends ReadonlyArray<infer U> ? ReadonlyArray<U> :
  T extends object ? { [K in keyof T]?: DeepPartial<T[K]> } :
