export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined) return base;
  if (Array.isArray(base)) {
    return Array.isArray(patch) ? ([...patch] as unknown as T) : base;
  }
  if (!isPlainObject(base)) {
    return patch as unknown as T;
  }
  const result = { ...(base as Record<string, unknown>) };
  for (const key in patch) {
    if (!Object.prototype.hasOwnProperty.call(patch, key)) continue;
    const pVal = (patch as Record<string, unknown>)[key];
    if (pVal === undefined) continue;
    const bVal = (base as Record<string, unknown>)[key];
    if (Array.isArray(bVal)) {
      if (Array.isArray(pVal)) {
        result[key] = [...pVal];
      }
    } else if (isPlainObject(bVal) && isPlainObject(pVal)) {
      result[key] = applyPatch(bVal, pVal as DeepPartial<typeof bVal>);
    } else {
      result[key] = pVal;
    }
  }
  return result as T;
